function refresh(){if(!window.prospectUser)return;if(!$('wfFrom').value)$('wfFrom').value=today();if(!$('wfTo').value)$('wfTo').value=today();renderList();renderToday();renderClosureReport();if(dialog.open)updateDialogSummary();}
window.refreshWorkflow=refresh;
window.closeWorkflow=()=>{for(const timer of draftTimers.values())clearTimeout(timer);draftTimers.clear();if(dialog.open)dialog.close();activeTel=null;listStamp='';};
document.addEventListener('click',e=>{const a=e.target.closest?.('a[href]');if(!a)return;let u;try{u=new URL(a.href);}catch{return;}if(u.hostname!=='wa.me'&&u.protocol!=='tel:')return;const tel=normalizarTelefone(u.protocol==='tel:'?u.pathname:u.pathname.slice(1)),h=find(tel);if(h&&['nao','invalido'].includes(h.status)){e.preventDefault();e.stopImmediatePropagation();showToast('Contato encerrado por recusa ou destino incorreto. Não enviar nova abordagem.');}},true);
const oldControls=window.prospectControls;window.prospectControls=h=>(oldControls?oldControls(h):'')+'<button type="button" class="btn btn-ghost btn-sm wf-open" onclick="openLeadWorkflow(\''+normalizarTelefone(h.telNum||h.tel)+'\')">Abrir atendimento passo a passo</button>';
window.prospectMessage=h=>W.message(h,context(),'auto');
const originalContact=registrarContato;registrarContato=function(tel){const h=find(tel);if(!h||!window.prospectCanWork(tel)||W.terminal(h.status))return;const kind=h.lastContactAt||h.status&&h.status!=='novo'?'return':'initial';originalContact(tel);patch(tel,{lastContactAt:now(),lastContactKind:kind});refresh();};
const originalStatus=setStatus,originalQuick=setQuickStatus;
function statusGuard(tel,status){const h=find(tel);if(!h||!window.prospectCanWork(tel))return false;const error=W.stageError(h,status)||W.closureError(h,status);if(error){showToast(error);window.openLeadWorkflow(tel);saveStatus(error);if(W.closeReasons[status]){$('wfClosure').open=true;$('wf-closeReason').focus();}return false;}return true;}
setStatus=function(tel,status){if(!statusGuard(tel,status))return;const h=find(tel);if(status==='proposta'&&W.approved(h)){patch(tel,{quoteState:'sent',quoteSentAt:now()});}originalStatus(tel,status);if(W.terminal(status)&&find(tel)?.status===status)patch(tel,{followUp:'',nextAction:''});refresh();};
setQuickStatus=function(tel,status){if(!statusGuard(tel,status))return;const h=find(tel);if(status==='proposta'&&W.approved(h)){patch(tel,{quoteState:'sent',quoteSentAt:now()});}originalQuick(tel,status);if(W.terminal(status)&&find(tel)?.status===status)patch(tel,{followUp:'',nextAction:''});refresh();};
const originalSwitch=switchTab;switchTab=function(id,el){originalSwitch(id,el);refresh();};
